      '--dsw-alias-bg-overlay': { light: 'rgba(6,14,22,.6)', dark: 'rgba(6,14,22,.6)' },
      '--dsw-alias-bg-module-platform': { light: 'rgba(14,28,40,.5)', dark: 'rgba(14,28,40,.5)' },
